def check_conditions(m, n, p):
    # Condition 1: m^2 + n = p^a, a >= 2
    c1 = m**2 + n

    # Check if c1 is a power of p
    if p <= 1: return False

    # Check power
    try:
        a = round(math.log(c1, p))
        if abs(math.log(c1, p) - a) > 1e-9:
            return False 
        if a < 2:
            return False 
    except ValueError:
        return False 

    # Condition 2: m + n^2 = p^b, b >= 2
    c2 = m + n**2

    # Check power
    try:
        b = round(math.log(c2, p))
        if abs(math.log(c2, p) - b) > 1e-9:
            return False
        if b < 2:
            return False
    except ValueError:
        return False

    return True

def search_solutions(M_max, N_max, P_list):
    solutions = set()
    for m in range(1, M_max + 1):
        for n in range(1, N_max + 1):
            for p in P_list:
                if check_conditions(m, n, p):
                    solutions.add((m, n, p))
    return list(solutions)

