import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_prime_power_exponent(N, p):
    if N <= 0 or p <= 1:
        return 0
    if N == 1:
        return 0
    while N > 0 and N % p == 0:
        N //= p
    return 0 # Return 0 if not a pure power of p

def find_solutions(M_max, N_max):
    solutions = []
    primes = [p for p in range(2, 421) if is_prime(p)] # Max value is 420

    for m in range(1, M_max + 1):
        for n in range(1, N_max + 1):
            S1 = m**2 + n
            S2 = m + n**2

            # Check for primes p that could satisfy the conditions
            for p in primes:
                if p > S1 and p > S2:
                    continue

                # Check S1 = p^a, a >= 2
                try:
                    a = round(math.log(S1, p))
                    if abs(p**a - S1) < 1e-9 and a >= 2:

                        # Check S2 = p^b, b >= 2
                        try:
                            b = round(math.log(S2, p))
                            if abs(p**b - S2) < 1e-9 and b >= 2:
                                solutions.append((m, n, p))
                        except ValueError:
                            pass # S2 is not a power of p

                except ValueError:
                    pass # S1 is not a power of p

    # Remove duplicates, as the loop structure might find the same triple multiple times if we didn't structure it perfectly, 
    # though with p fixed, this shouldn't be an issue.
    return list(set(solutions))

