def solve_problem(M_max, N_max, primes=[2, 3]):
    solutions = []
    for p in primes:
        for m in range(1, M_max + 1):
            for n in range(1, N_max + 1):
                # Check constraints: exponents must be > 1
                m2_plus_n = m**2 + n
                m_plus_n2 = m + n**2

                if m2_plus_n <= 1 or m_plus_n2 <= 1:
                    continue

                # Check if both are powers of p
                a = None
                b = None

                # Find exponent 'a' for m^2+n
                if m2_plus_n % p == 0:
                    temp_a = m2_plus_n
                    exp_a = 0
                    while temp_a > 1 and temp_a % p == 0:
                        temp_a //= p
                        exp_a += 1
                    if temp_a == 1 and exp_a > 1:
                        a = exp_a

                # Find exponent 'b' for m+n^2
                if m_plus_n2 % p == 0:
                    temp_b = m_plus_n2
